def floodFill(image, sr, sc, color):
    orig = image[sr][sc]
    if orig == color: return image
    m, n = len(image), len(image[0])
    def dfs(r, c):
        if 0 <= r < m and 0 <= c < n and image[r][c] == orig:
            image[r][c] = color
            dfs(r+1, c); dfs(r-1, c); dfs(r, c+1); dfs(r, c-1)
    dfs(sr, sc)
    return image

